        headers = {}
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"urls\" : [ \"<img src=x onerror=alert('XSS')>\" ] " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/check_online_status",
                    headers=headers, cookies=cookies_pyload, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
